84	    }
85	    .circle-container:is(:hover, :focus-visible) circle {
86	      fill: #e8f4f8;
87	      r: 205;
88	      stroke: rgba(255, 255, 255, 0.4);
89	    }
90	    .circle-container.active circle {
91	      fill: var(--color-gold);
92	      stroke: rgba(255, 215, 0, 0.3);
93	      animation: pulse-active 0.6s ease-in-out;
