340	<body>
341	  <main>
342	    <button class="circle-container" id="decorative-circle" aria-label="Interactive circle - press Space to toggle, double-click to change color" aria-pressed="false">
343	      <svg viewBox="0 0 400 400" aria-hidden="true" role="presentation">
344	        <circle cx="200" cy="200" r="200"/>
345	      </svg>
346	    </button>
347	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
348	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click to activate • Double-click to change color</div>
349	    <div class="controls" role="group" aria-label="Circle controls">
350	      <button class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
351	      <button class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
352	    </div>
353	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
354	  </main>
355	
356	  <script>
357	    const CONFIG = {
358	      storageKey: 'circle-state',
359	      tapDelay: 300,
360	      colorShiftDuration: 500,
361	      colorModes: [
362	        { class: 'default', name: 'Default White' },
363	        { class: 'color-mode-1', name: 'Pink' },
364	        { class: 'color-mode-2', name: 'Teal' },
365	        { class: 'color-mode-3', name: 'Mint' }
366	      ],
367	      isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0,
368	      pulseInterval: 2500
369	    };
370	
371	    const el = {
372	      circle: document.getElementById('decorative-circle'),
373	      hint: document.getElementById('hint-text'),
374	      modeIndicator: document.getElementById('mode-indicator'),
375	      cycleBtn: document.getElementById('cycle-btn'),
376	      resetBtn: document.getElementById('reset-btn')
377	    };
378	
379	    let state = { active: false, colorMode: 0 };
380	    let lastTapTime = 0;
381	    let tapTimeout = null;
382	    let animatingColorShift = false;
383	
384	    const getColorModeClass = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].class;
385	    const getColorModeName = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].name;
386	
387	    const storage = {
388	      save() {
389	        try {
390	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
391	        } catch {
392	          // Silently fail if localStorage is unavailable or quota exceeded
393	        }
394	      },
395	      load() {
396	        try {
397	          const saved = localStorage.getItem(CONFIG.storageKey);
398	          if (saved) {
399	            const parsed = JSON.parse(saved);
400	            if (parsed && typeof parsed === 'object') {
401	              state = { ...state, ...parsed };
402	            }
403	          }
404	        } catch {
405	          // Silently fail if parsing fails
406	        }
407	      }
408	    };
409	
410	    const updateClasses = () => {
411	      const colorClasses = CONFIG.colorModes.map(m => m.class);
412	      el.circle.classList.remove('active', ...colorClasses);
413	      el.circle.setAttribute('aria-pressed', state.active);
414	      if (state.active) el.circle.classList.add('active');
415	      if (state.colorMode > 0) el.circle.classList.add(getColorModeClass(state.colorMode));
416	    };
417	
418	    const updateUI = () => {
419	      const mainText = state.active ? 'Active!' : 'Click to activate';
420	      let hintParts = [mainText];
421	
422	      if (CONFIG.isTouch) {
423	        hintParts.push(state.active ? 'Tap to change color' : 'Tap twice to change color');
424	      } else {
425	        hintParts.push('Double-click to change color');
426	      }
427	
428	      el.hint.textContent = hintParts.join(' • ');
429	
430	      const showMode = state.active && state.colorMode > 0;
431	      el.modeIndicator.classList.toggle('visible', showMode);
432	      if (showMode) {
433	        const modeName = getColorModeName(state.colorMode);
434	        el.modeIndicator.textContent = modeName;
435	      }
436	    };
437	
438	    const applyState = () => {
439	      updateClasses();
440	      updateUI();
441	    };
442	
443	    const toggleActive = () => {
444	      state.active = !state.active;
445	      applyState();
446	      storage.save();
447	    };
448	
449	    const cycleColor = () => {
450	      if (animatingColorShift) return;
451	      animatingColorShift = true;
452	      state.colorMode = (state.colorMode + 1) % CONFIG.colorModes.length;
453	      state.active = true;
454	      el.circle.classList.add('color-shifting');
455	      setTimeout(() => {
456	        el.circle.classList.remove('color-shifting');
457	        animatingColorShift = false;
458	      }, CONFIG.colorShiftDuration);
459	      applyState();
460	      storage.save();
461	    };
462	
463	    const resetState = () => {
464	      state = { active: false, colorMode: 0 };
465	      applyState();
466	      storage.save();
467	    };
468	
469	    const handleDblClick = (e) => {
470	      e.preventDefault();
471	      cycleColor();
472	    };
473	
474	    const handleTouchEnd = (e) => {
475	      const now = Date.now();
476	      if (now - lastTapTime < CONFIG.tapDelay && lastTapTime > 0) {
477	        cycleColor();
478	        lastTapTime = 0;
479	        clearTimeout(tapTimeout);
480	      } else {
481	        lastTapTime = now;
482	        clearTimeout(tapTimeout);
483	        tapTimeout = setTimeout(() => { lastTapTime = 0; }, CONFIG.tapDelay);
484	      }
485	    };
486	
487	    const keyHandlers = {
488	      ' ': toggleActive,
489	      'enter': toggleActive,
490	      'c': cycleColor,
491	      'r': resetState
492	    };
493	
494	    const handleKeyDown = (e) => {
495	      const handler = keyHandlers[e.key.toLowerCase()];
496	      if (handler) {
497	        e.preventDefault();
498	        handler();
499	      }
500	    };
501	
502	    const initListeners = () => {
503	      el.circle.addEventListener('click', toggleActive);
504	      el.circle.addEventListener('dblclick', handleDblClick);
505	      el.circle.addEventListener('touchend', handleTouchEnd);
506	      el.circle.addEventListener('blur', () => {
507	        lastTapTime = 0;
508	        clearTimeout(tapTimeout);
509	      });
510	      document.addEventListener('keydown', handleKeyDown);
511	      el.cycleBtn.addEventListener('click', cycleColor);
512	      el.resetBtn.addEventListener('click', resetState);
513	    };
514	
515	    const initApp = () => {
516	      storage.load();
517	      applyState();
518	      initListeners();
519	      requestAnimationFrame(() => el.circle.focus());
520	    };
521	
522	    if (document.readyState === 'loading') {
523	      document.addEventListener('DOMContentLoaded', initApp);
524	    } else {
525	      initApp();
526	    }
527	  </script>
528	</body>
529	</html>
